INSERT INTO `students` (`id`, `nama`, `nisn`, `tanggal_lahir`, `kelas`, `status_kelulusan`, `mode_drama`, `pesan_khusus`, `sudah_akses`, `jumlah_akses`, `akses_terakhir`, `created_at`, `updated_at`) VALUES
(100, 'MEYLAN LASATUA', '0103160132', '2010-06-17', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Meylan Lasatua, selamat atas kelulusanmu dari MTsN 1 Pohuwato. Teruslah menjaga akhlak, sebab nilai terbaik seorang lulusan bukan hanya prestasi, tetapi juga sikap yang mulia. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga Allah meridai perjalananmu, menguatkan semangat belajarmu, dan menjadikanmu insan yang berguna bagi sesama.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(101, 'YUYIN NUPU', '0117513859', '2011-06-14', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Yuyin Nupu, hari kelulusan ini menjadi bukti bahwa perjuangan dan kesungguhanmu selama di MTsN 1 Pohuwato tidak sia-sia. Semakin jauh langkahmu, semoga semakin kuat pula kerendahan hati dan rasa hormatmu kepada orang lain. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga setiap langkah setelah kelulusan ini dipenuhi petunjuk Allah, keberkahan ilmu, dan kebahagiaan bagi keluargamu.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(102, 'ENJEL ABDULRAHMAN', '0107330736', '2010-09-24', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Enjel Abdulrahman, kelulusanmu hari ini adalah awal dari perjalanan baru yang lebih luas. Ingatlah bahwa ilmu yang baik akan menuntunmu untuk semakin rendah hati dan menghargai orang lain. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga setiap ilmu dan pengalaman di MTsN 1 Pohuwato menjadi bekal yang bermanfaat dalam meraih masa depan yang cerah.', 1, 1, '2026-05-14 07:48:04', '2026-05-14 07:47:21', '2026-05-14 07:48:04'),
(103, 'SALSABILA ALHASNI', '0111036390', '2011-10-29', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Salsabila Alhasni, keluarga besar MTsN 1 Pohuwato turut bangga atas capaian kelulusanmu. Tetaplah sederhana dalam keberhasilan dan kuat dalam menghadapi tantangan berikutnya. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga Allah menjadikanmu pribadi yang cerdas, santun, kuat, dan selalu membawa kebaikan di mana pun berada.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(104, 'AYUDYA FAMALA NUR I. AYUBA', '0103993787', '2010-06-01', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Ayudya Famala Nur I. Ayuba, keberhasilan ini adalah hasil dari doa, usaha, dan ketekunan yang telah kamu jalani. Semoga keberhasilan ini membuatmu semakin dewasa, bijak, dan bertanggung jawab. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga Allah selalu menjaga langkahmu, melapangkan jalan cita-citamu, dan menjadikanmu pribadi yang rendah hati serta berprestasi.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(105, 'AL FITRA MULANE', '0109012847', '2010-08-13', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Al Fitra Mulane, selamat melangkah menuju jenjang pendidikan berikutnya dengan penuh keyakinan. Jadilah lulusan yang kuat dalam ilmu, lembut dalam sikap, dan tulus dalam berbuat baik. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga ilmu yang kamu bawa menjadi cahaya, menuntunmu untuk sukses dunia dan akhirat.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(106, 'MOHAMAD AL FADHIEL POLONTALO', '0101501556', '2010-07-19', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Mohamad Al Fadhiel Polontalo, hari ini kamu menutup satu bab penting di MTsN 1 Pohuwato dengan penuh kebanggaan. Tetaplah rendah hati, karena keberhasilan sejati adalah ketika ilmu membuatmu semakin santun dan bermanfaat bagi sesama. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga ilmu yang diperoleh menjadi berkah, menguatkan akhlakmu, dan mengantarkanmu menuju masa depan yang penuh kebaikan.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(107, 'PRAMA CHAIRUL JHOSEPH', '0111306686', '2011-03-20', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Prama Chairul Jhoseph, kelulusan ini semoga menjadi pintu pembuka bagi masa depan yang lebih baik. Bawalah nama baik madrasah dengan sikap yang sopan, jujur, dan bertanggung jawab di mana pun kamu berada. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga kamu selalu diberi kesehatan, kemudahan belajar, dan keberkahan dalam setiap langkah menuju cita-cita.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(108, 'LEYDI ADELVIRA', '3113594885', '2011-01-08', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Leydi Adelvira, perjalananmu di MTsN 1 Pohuwato telah memberi banyak pelajaran berharga. Prestasi akan lebih indah jika disertai adab, rasa syukur, dan kepedulian terhadap sesama. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga Allah memberkahi ilmumu, memudahkan langkahmu, dan menjadikanmu anak yang berbakti serta bermanfaat bagi agama, keluarga, dan bangsa.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(109, 'NADILLA PUTRI NAZMUDIN', '0108580379', '2010-11-30', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Nadilla Putri Nazmudin, selamat atas pencapaian yang membanggakan ini sebagai lulusan MTsN 1 Pohuwato. Jangan berhenti berbuat baik, karena keberhasilan akan lebih bermakna saat memberi manfaat bagi banyak orang. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga masa depanmu dipenuhi keberhasilan yang diraih dengan usaha, doa, dan akhlak yang mulia.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(110, 'MOHAMAD SAPUTRA FAIDAH', '3101882725', '2010-09-15', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Mohamad Saputra Faidah, teruslah membawa semangat belajar yang telah tumbuh selama berada di madrasah ini. Gunakan ilmu yang kamu peroleh untuk kebaikan, bukan untuk merasa lebih tinggi dari orang lain. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga keberhasilan ini menjadi awal dari masa depan yang lebih indah, penuh berkah, dan membawa manfaat untuk banyak orang.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(111, 'AGHUTRIAN KANGO', '0116682755', '2011-05-08', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Aghutrian Kango, kelulusanmu adalah amanah untuk terus menjadi pribadi yang lebih baik. Tetaplah menunduk dalam syukur, lalu bangkit dengan semangat untuk meraih cita-cita yang lebih tinggi. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga Allah menuntunmu kepada jalan yang baik, menjaga adabmu, dan mengangkat derajatmu dengan ilmu yang bermanfaat.', 1, 1, '2026-05-14 07:51:28', '2026-05-14 07:47:21', '2026-05-14 07:51:28'),
(112, 'YUSUF OLII', '0108493554', '2010-10-08', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Yusuf Olii, semoga momen kelulusan ini menjadi penguat langkahmu dalam meraih cita-cita. Semoga kamu selalu menjaga adab kepada orang tua, guru, teman, dan siapa pun yang kamu temui. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga Allah memudahkan pendidikanmu selanjutnya dan menjadikan semua ilmu yang kamu pelajari sebagai amal yang bermanfaat.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(113, 'FATMAWATI NAYLA TANGAHU', '0119329126', '2011-01-26', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Fatmawati Nayla Tangahu, hari ini menjadi tanda bahwa kamu mampu menyelesaikan proses belajar dengan baik. Jangan biarkan keberhasilan membuatmu tinggi hati; jadikan ia alasan untuk semakin bersyukur dan memperbaiki diri. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga kelulusan ini membawa keberkahan, membuka jalan kebaikan, dan menjadi awal dari prestasi-prestasi berikutnya.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(114, 'ADITYA SAMARANG', '3112970187', '2011-01-02', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Aditya Samarang, selamat menjadi alumni MTsN 1 Pohuwato yang siap melangkah lebih jauh. Jadikan kelulusan ini sebagai pengingat untuk terus belajar tanpa merasa paling hebat. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga kamu tumbuh menjadi alumni yang membanggakan, tetap berakhlak baik, dan selalu dirahmati Allah dalam setiap usaha.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(115, 'SITI FATIYAH SUTRISNO', '0117314111', '2011-10-18', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Siti Fatiyah Sutrisno, capaian ini patut disyukuri sebagai karunia Allah dan buah dari kerja kerasmu. Teruslah menjadi pribadi yang tidak mudah puas, namun tetap santun dalam setiap pencapaian. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga Allah meridai perjalananmu, menguatkan semangat belajarmu, dan menjadikanmu insan yang berguna bagi sesama.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(116, 'SELMI ZESKIA MENU', '0117074458', '2011-05-29', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Selmi Zeskia Menu, teruslah menjaga semangat dan adab baik yang telah kamu pelajari di MTsN 1 Pohuwato. Jagalah tutur kata dan perilaku, karena keduanya akan menjadi cerminan baik bagi dirimu dan madrasahmu. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga setiap langkah setelah kelulusan ini dipenuhi petunjuk Allah, keberkahan ilmu, dan kebahagiaan bagi keluargamu.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(117, 'SRI APRILIA DJUMA', '0116236082', '2011-04-02', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Sri Aprilia Djuma, kelulusan ini bukan akhir, melainkan awal untuk meraih keberhasilan yang lebih besar. Teruslah melangkah dengan percaya diri, namun jangan pernah kehilangan sikap hormat dan rendah hati. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga setiap ilmu dan pengalaman di MTsN 1 Pohuwato menjadi bekal yang bermanfaat dalam meraih masa depan yang cerah.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(118, 'MOHAMAD ABDUL FAZRI PIKOLI', '0114214322', '2011-01-27', 'Kelas 9 - KELAS IX A', 'LULUS', 'Normal', 'Mohamad Abdul Fazri Pikoli, semoga keberhasilan hari ini membuatmu semakin yakin untuk terus belajar dan berprestasi. Jangan lupa bahwa setiap pencapaian lahir dari doa, bimbingan, dan dukungan banyak orang. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga Allah menjadikanmu pribadi yang cerdas, santun, kuat, dan selalu membawa kebaikan di mana pun berada.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(119, 'HUMAIRA ARIF', '3107141887', '2010-08-18', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Humaira Arif, keluarga besar madrasah bangga melihatmu sampai pada tahap kelulusan ini. Buktikan bahwa lulusan madrasah mampu tampil unggul tanpa meninggalkan akhlak yang mulia. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga Allah selalu menjaga langkahmu, melapangkan jalan cita-citamu, dan menjadikanmu pribadi yang rendah hati serta berprestasi.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(120, 'MOHAMAD FAKHRI PADUNGGALA', '3111216831', '2011-03-24', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Mohamad Fakhri Padunggala, selamat atas kelulusanmu dari MTsN 1 Pohuwato. Teruslah menjaga akhlak, sebab nilai terbaik seorang lulusan bukan hanya prestasi, tetapi juga sikap yang mulia. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga ilmu yang kamu bawa menjadi cahaya, menuntunmu untuk sukses dunia dan akhirat.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(121, 'MUH. ABDUL HAFIZ MANGOPA', '0103144442', '2010-04-14', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Muh. Abdul Hafiz Mangopa, hari kelulusan ini menjadi bukti bahwa perjuangan dan kesungguhanmu selama di MTsN 1 Pohuwato tidak sia-sia. Semakin jauh langkahmu, semoga semakin kuat pula kerendahan hati dan rasa hormatmu kepada orang lain. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga ilmu yang diperoleh menjadi berkah, menguatkan akhlakmu, dan mengantarkanmu menuju masa depan yang penuh kebaikan.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(122, 'HELDY PUTRI HARUN', '0115474103', '2011-05-06', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Heldy Putri Harun, kelulusanmu hari ini adalah awal dari perjalanan baru yang lebih luas. Ingatlah bahwa ilmu yang baik akan menuntunmu untuk semakin rendah hati dan menghargai orang lain. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga kamu selalu diberi kesehatan, kemudahan belajar, dan keberkahan dalam setiap langkah menuju cita-cita.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(123, 'NUR FITRIA KALAPATI', '0105042629', '2010-08-25', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Nur Fitria Kalapati, keluarga besar MTsN 1 Pohuwato turut bangga atas capaian kelulusanmu. Tetaplah sederhana dalam keberhasilan dan kuat dalam menghadapi tantangan berikutnya. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga Allah memberkahi ilmumu, memudahkan langkahmu, dan menjadikanmu anak yang berbakti serta bermanfaat bagi agama, keluarga, dan bangsa.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(124, 'NOVITA HIZRIA MORA', '0103945628', '2010-11-17', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Novita Hizria Mora, keberhasilan ini adalah hasil dari doa, usaha, dan ketekunan yang telah kamu jalani. Semoga keberhasilan ini membuatmu semakin dewasa, bijak, dan bertanggung jawab. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga masa depanmu dipenuhi keberhasilan yang diraih dengan usaha, doa, dan akhlak yang mulia.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(125, 'NATASYA PUTRI RAUF', '0118782096', '2011-05-23', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Natasya Putri Rauf, selamat melangkah menuju jenjang pendidikan berikutnya dengan penuh keyakinan. Jadilah lulusan yang kuat dalam ilmu, lembut dalam sikap, dan tulus dalam berbuat baik. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga keberhasilan ini menjadi awal dari masa depan yang lebih indah, penuh berkah, dan membawa manfaat untuk banyak orang.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(126, 'ADRIAN KAI', '0119157226', '2011-04-05', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Adrian Kai, hari ini kamu menutup satu bab penting di MTsN 1 Pohuwato dengan penuh kebanggaan. Tetaplah rendah hati, karena keberhasilan sejati adalah ketika ilmu membuatmu semakin santun dan bermanfaat bagi sesama. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga Allah menuntunmu kepada jalan yang baik, menjaga adabmu, dan mengangkat derajatmu dengan ilmu yang bermanfaat.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(127, 'YOLANDA SALSABILA ABDULLAH', '0118423277', '2011-01-20', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Yolanda Salsabila Abdullah, kelulusan ini semoga menjadi pintu pembuka bagi masa depan yang lebih baik. Bawalah nama baik madrasah dengan sikap yang sopan, jujur, dan bertanggung jawab di mana pun kamu berada. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga Allah memudahkan pendidikanmu selanjutnya dan menjadikan semua ilmu yang kamu pelajari sebagai amal yang bermanfaat.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(128, 'ZIVANA NATASYA S BUNA', '0115686907', '2011-03-31', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Zivana Natasya S Buna, perjalananmu di MTsN 1 Pohuwato telah memberi banyak pelajaran berharga. Prestasi akan lebih indah jika disertai adab, rasa syukur, dan kepedulian terhadap sesama. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga kelulusan ini membawa keberkahan, membuka jalan kebaikan, dan menjadi awal dari prestasi-prestasi berikutnya.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(129, 'ALISSA MAYULU', '0104514546', '2010-02-16', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Alissa Mayulu, selamat atas pencapaian yang membanggakan ini sebagai lulusan MTsN 1 Pohuwato. Jangan berhenti berbuat baik, karena keberhasilan akan lebih bermakna saat memberi manfaat bagi banyak orang. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga kamu tumbuh menjadi alumni yang membanggakan, tetap berakhlak baik, dan selalu dirahmati Allah dalam setiap usaha.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(130, 'APRILIA TINE', '3118065017', '2011-04-11', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Aprilia Tine, teruslah membawa semangat belajar yang telah tumbuh selama berada di madrasah ini. Gunakan ilmu yang kamu peroleh untuk kebaikan, bukan untuk merasa lebih tinggi dari orang lain. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga Allah meridai perjalananmu, menguatkan semangat belajarmu, dan menjadikanmu insan yang berguna bagi sesama.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(131, 'ZULKARNAIN MONOARFA', '0102893002', '2010-12-13', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Zulkarnain Monoarfa, kelulusanmu adalah amanah untuk terus menjadi pribadi yang lebih baik. Tetaplah menunduk dalam syukur, lalu bangkit dengan semangat untuk meraih cita-cita yang lebih tinggi. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga setiap langkah setelah kelulusan ini dipenuhi petunjuk Allah, keberkahan ilmu, dan kebahagiaan bagi keluargamu.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(132, 'ISMAIL PAKAYA', '0113888127', '2011-02-15', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Ismail Pakaya, semoga momen kelulusan ini menjadi penguat langkahmu dalam meraih cita-cita. Semoga kamu selalu menjaga adab kepada orang tua, guru, teman, dan siapa pun yang kamu temui. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga setiap ilmu dan pengalaman di MTsN 1 Pohuwato menjadi bekal yang bermanfaat dalam meraih masa depan yang cerah.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(133, 'MOH. YUDISTIRA ALFARIZHI', '3114273993', '2011-07-27', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Moh. Yudistira Alfarizhi, hari ini menjadi tanda bahwa kamu mampu menyelesaikan proses belajar dengan baik. Jangan biarkan keberhasilan membuatmu tinggi hati; jadikan ia alasan untuk semakin bersyukur dan memperbaiki diri. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga Allah menjadikanmu pribadi yang cerdas, santun, kuat, dan selalu membawa kebaikan di mana pun berada.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(134, 'SITI RAFIKA PUTRI ILAHUDE', '0114005105', '2011-01-16', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Siti Rafika Putri Ilahude, selamat menjadi alumni MTsN 1 Pohuwato yang siap melangkah lebih jauh. Jadikan kelulusan ini sebagai pengingat untuk terus belajar tanpa merasa paling hebat. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga Allah selalu menjaga langkahmu, melapangkan jalan cita-citamu, dan menjadikanmu pribadi yang rendah hati serta berprestasi.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(135, 'MOHAMAD FADIL NUSI', '0111487192', '2011-06-10', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Mohamad Fadil Nusi, capaian ini patut disyukuri sebagai karunia Allah dan buah dari kerja kerasmu. Teruslah menjadi pribadi yang tidak mudah puas, namun tetap santun dalam setiap pencapaian. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga ilmu yang kamu bawa menjadi cahaya, menuntunmu untuk sukses dunia dan akhirat.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(136, 'RAIHANNA GHASSANIA MASSIE', '0111140525', '2011-06-16', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Raihanna Ghassania Massie, teruslah menjaga semangat dan adab baik yang telah kamu pelajari di MTsN 1 Pohuwato. Jagalah tutur kata dan perilaku, karena keduanya akan menjadi cerminan baik bagi dirimu dan madrasahmu. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga ilmu yang diperoleh menjadi berkah, menguatkan akhlakmu, dan mengantarkanmu menuju masa depan yang penuh kebaikan.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(137, 'VANEZA PUTRI LAMANGGI', '0107803021', '2010-12-01', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Vaneza Putri Lamanggi, kelulusan ini bukan akhir, melainkan awal untuk meraih keberhasilan yang lebih besar. Teruslah melangkah dengan percaya diri, namun jangan pernah kehilangan sikap hormat dan rendah hati. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga kamu selalu diberi kesehatan, kemudahan belajar, dan keberkahan dalam setiap langkah menuju cita-cita.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(138, 'JAHRA KATILI', '0102974211', '2010-11-29', 'Kelas 9 - KELAS IX B', 'LULUS', 'Normal', 'Jahra Katili, semoga keberhasilan hari ini membuatmu semakin yakin untuk terus belajar dan berprestasi. Jangan lupa bahwa setiap pencapaian lahir dari doa, bimbingan, dan dukungan banyak orang. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga Allah memberkahi ilmumu, memudahkan langkahmu, dan menjadikanmu anak yang berbakti serta bermanfaat bagi agama, keluarga, dan bangsa.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
