(181, 'SASKIYA ISMAIL', '0108037364', '2010-05-11', 'Kelas 9 - KELAS IX E', 'LULUS', 'Normal', 'Saskiya Ismail, hari kelulusan ini menjadi bukti bahwa perjuangan dan kesungguhanmu selama di MTsN 1 Pohuwato tidak sia-sia. Semakin jauh langkahmu, semoga semakin kuat pula kerendahan hati dan rasa hormatmu kepada orang lain. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga ilmu yang diperoleh menjadi berkah, menguatkan akhlakmu, dan mengantarkanmu menuju masa depan yang penuh kebaikan.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(182, 'GIO SAPUTRA YUSUP', '0117888114', '2011-01-27', 'Kelas 9 - KELAS IX E', 'LULUS', 'Normal', 'Gio Saputra Yusup, kelulusanmu hari ini adalah awal dari perjalanan baru yang lebih luas. Ingatlah bahwa ilmu yang baik akan menuntunmu untuk semakin rendah hati dan menghargai orang lain. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga kamu selalu diberi kesehatan, kemudahan belajar, dan keberkahan dalam setiap langkah menuju cita-cita.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(183, 'CINTA RAMADANI ALULU', '0112521127', '2011-07-25', 'Kelas 9 - KELAS IX E', 'LULUS', 'Normal', 'Cinta Ramadani Alulu, keluarga besar MTsN 1 Pohuwato turut bangga atas capaian kelulusanmu. Tetaplah sederhana dalam keberhasilan dan kuat dalam menghadapi tantangan berikutnya. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga Allah memberkahi ilmumu, memudahkan langkahmu, dan menjadikanmu anak yang berbakti serta bermanfaat bagi agama, keluarga, dan bangsa.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(184, 'AMELIA MUTHMAINNAH BOLILIO', '0113281028', '2011-03-07', 'Kelas 9 - KELAS IX E', 'LULUS', 'Normal', 'Amelia Muthmainnah Bolilio, keberhasilan ini adalah hasil dari doa, usaha, dan ketekunan yang telah kamu jalani. Semoga keberhasilan ini membuatmu semakin dewasa, bijak, dan bertanggung jawab. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga masa depanmu dipenuhi keberhasilan yang diraih dengan usaha, doa, dan akhlak yang mulia.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(185, 'NUR KHALIZHA HASAN', '3094950352', '2009-10-10', 'Kelas 9 - KELAS IX E', 'LULUS', 'Normal', 'Nur Khalizha Hasan, selamat melangkah menuju jenjang pendidikan berikutnya dengan penuh keyakinan. Jadilah lulusan yang kuat dalam ilmu, lembut dalam sikap, dan tulus dalam berbuat baik. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga keberhasilan ini menjadi awal dari masa depan yang lebih indah, penuh berkah, dan membawa manfaat untuk banyak orang.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21');
INSERT INTO `students` (`id`, `nama`, `nisn`, `tanggal_lahir`, `kelas`, `status_kelulusan`, `mode_drama`, `pesan_khusus`, `sudah_akses`, `jumlah_akses`, `akses_terakhir`, `created_at`, `updated_at`) VALUES
(186, 'NUR LILLAH MANISA', '0119885767', '2011-03-24', 'Kelas 9 - KELAS IX E', 'LULUS', 'Normal', 'Nur Lillah Manisa, hari ini kamu menutup satu bab penting di MTsN 1 Pohuwato dengan penuh kebanggaan. Tetaplah rendah hati, karena keberhasilan sejati adalah ketika ilmu membuatmu semakin santun dan bermanfaat bagi sesama. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga Allah menuntunmu kepada jalan yang baik, menjaga adabmu, dan mengangkat derajatmu dengan ilmu yang bermanfaat.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(187, 'DESY SULISTIANA ALULU', '3104084470', '2010-12-21', 'Kelas 9 - KELAS IX E', 'LULUS', 'Normal', 'Desy Sulistiana Alulu, kelulusan ini semoga menjadi pintu pembuka bagi masa depan yang lebih baik. Bawalah nama baik madrasah dengan sikap yang sopan, jujur, dan bertanggung jawab di mana pun kamu berada. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga Allah memudahkan pendidikanmu selanjutnya dan menjadikan semua ilmu yang kamu pelajari sebagai amal yang bermanfaat.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(188, 'CHAIKAL BUMULO', '3116295221', '2011-01-22', 'Kelas 9 - KELAS IX E', 'LULUS', 'Normal', 'Chaikal Bumulo, perjalananmu di MTsN 1 Pohuwato telah memberi banyak pelajaran berharga. Prestasi akan lebih indah jika disertai adab, rasa syukur, dan kepedulian terhadap sesama. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga kelulusan ini membawa keberkahan, membuka jalan kebaikan, dan menjadi awal dari prestasi-prestasi berikutnya.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(189, 'NUR RAIHAN H. TABINGO', '3113254687', '2011-05-23', 'Kelas 9 - KELAS IX E', 'LULUS', 'Normal', 'Nur Raihan H. Tabingo, selamat atas pencapaian yang membanggakan ini sebagai lulusan MTsN 1 Pohuwato. Jangan berhenti berbuat baik, karena keberhasilan akan lebih bermakna saat memberi manfaat bagi banyak orang. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga kamu tumbuh menjadi alumni yang membanggakan, tetap berakhlak baik, dan selalu dirahmati Allah dalam setiap usaha.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(190, 'MARSYA STEVANI MAYANG', '0107883917', '2010-09-16', 'Kelas 9 - KELAS IX E', 'LULUS', 'Normal', 'Marsya Stevani Mayang, teruslah membawa semangat belajar yang telah tumbuh selama berada di madrasah ini. Gunakan ilmu yang kamu peroleh untuk kebaikan, bukan untuk merasa lebih tinggi dari orang lain. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga Allah meridai perjalananmu, menguatkan semangat belajarmu, dan menjadikanmu insan yang berguna bagi sesama.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(191, 'ZAHRATUN NISSA ISMAIL', '0112968472', '2011-04-27', 'Kelas 9 - KELAS IX E', 'LULUS', 'Normal', 'Zahratun Nissa Ismail, kelulusanmu adalah amanah untuk terus menjadi pribadi yang lebih baik. Tetaplah menunduk dalam syukur, lalu bangkit dengan semangat untuk meraih cita-cita yang lebih tinggi. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga setiap langkah setelah kelulusan ini dipenuhi petunjuk Allah, keberkahan ilmu, dan kebahagiaan bagi keluargamu.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(192, 'MOHAMMAD IBRAHIM TULIYABU', '0103445620', '2010-11-14', 'Kelas 9 - KELAS IX E', 'LULUS', 'Normal', 'Mohammad Ibrahim Tuliyabu, semoga momen kelulusan ini menjadi penguat langkahmu dalam meraih cita-cita. Semoga kamu selalu menjaga adab kepada orang tua, guru, teman, dan siapa pun yang kamu temui. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga setiap ilmu dan pengalaman di MTsN 1 Pohuwato menjadi bekal yang bermanfaat dalam meraih masa depan yang cerah.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(193, 'ABDUL KARIM LADIKU', '0112840906', '2011-02-03', 'Kelas 9 - KELAS IX E', 'LULUS', 'Normal', 'Abdul Karim Ladiku, hari ini menjadi tanda bahwa kamu mampu menyelesaikan proses belajar dengan baik. Jangan biarkan keberhasilan membuatmu tinggi hati; jadikan ia alasan untuk semakin bersyukur dan memperbaiki diri. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga Allah menjadikanmu pribadi yang cerdas, santun, kuat, dan selalu membawa kebaikan di mana pun berada.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(194, 'KHADIJAH SYANIE TAU\'E', '0109310941', '2010-10-17', 'Kelas 9 - KELAS IX E', 'LULUS', 'Normal', 'Khadijah Syanie Tau\'e, selamat menjadi alumni MTsN 1 Pohuwato yang siap melangkah lebih jauh. Jadikan kelulusan ini sebagai pengingat untuk terus belajar tanpa merasa paling hebat. Ingatlah bahwa di balik kelulusanmu ada doa, arahan, dan perhatian dari guru-guru MTsN 1 Pohuwato. Semoga Allah selalu menjaga langkahmu, melapangkan jalan cita-citamu, dan menjadikanmu pribadi yang rendah hati serta berprestasi.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(195, 'RESPATI S.MUDA', '0108129031', '2010-10-08', 'Kelas 9 - KELAS IX E', 'LULUS', 'Normal', 'Respati S.muda, capaian ini patut disyukuri sebagai karunia Allah dan buah dari kerja kerasmu. Teruslah menjadi pribadi yang tidak mudah puas, namun tetap santun dalam setiap pencapaian. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga ilmu yang kamu bawa menjadi cahaya, menuntunmu untuk sukses dunia dan akhirat.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(196, 'AYATUL HUSNA NENTO', '0103278401', '2010-07-14', 'Kelas 9 - KELAS IX E', 'LULUS', 'Normal', 'Ayatul Husna Nento, teruslah menjaga semangat dan adab baik yang telah kamu pelajari di MTsN 1 Pohuwato. Jagalah tutur kata dan perilaku, karena keduanya akan menjadi cerminan baik bagi dirimu dan madrasahmu. Jangan pernah melupakan guru-gurumu di MTsN 1 Pohuwato yang telah mendampingi proses tumbuh dan belajarmu. Semoga ilmu yang diperoleh menjadi berkah, menguatkan akhlakmu, dan mengantarkanmu menuju masa depan yang penuh kebaikan.', 0, 0, NULL, '2026-05-14 07:47:21', '2026-05-14 07:47:21'),
(197, 'Sawal', '1', '2026-05-13', 'IX A', 'LULUS', 'Normal', 'selamat menjadi alumni MTsN 1 Pohuwato yang siap melangkah lebih jauh. Jadikan kelulusan ini sebagai pengingat untuk terus belajar tanpa merasa paling hebat. Bawalah pesan-pesan baik dari guru-gurumu sebagai pegangan dalam menempuh pendidikan dan kehidupan berikutnya. Semoga kamu tumbuh menjadi alumni yang membanggakan, tetap berakhlak baik, dan selalu dirahmati Allah dalam setiap usaha.', 1, 12, '2026-05-14 09:17:24', '2026-05-14 07:50:19', '2026-05-14 09:17:24');

